    border-top: 1px solid var(--border, rgba(0,0,0,.12)); box-shadow: 0 18px 34px -22px rgba(0,0,0,.55); max-height: 76vh; overflow-y: auto;
  }
  header nav.nav-open, .site-header nav.nav-open, .navbar nav.nav-open, header .nav-links.nav-open { display: flex !important; }
  header nav ul, .site-header nav ul, .navbar nav ul { flex-direction: column !important; align-items: flex-start !important; width: 100%; }
  header nav a, .site-header nav a, .navbar nav a, header .nav-links a { width: 100%; padding: .55rem 0; }
}

/* ── Claude QA polish ── */
/* --- Polish additions: spacing rhythm, shadows, transitions, focus states --- */

/* Smooth, consistent transitions for interactive elements */
a,
button,
input,
select,
textarea,
.card,
[class*="btn"],
[class*="card"] {
  transition: box-shadow 0.2s ease, transform 0.15s ease, background-color 0.2s ease,
    border-color 0.2s ease, color 0.2s ease;
}

/* Refined hover lift for card-like containers */
.card:hover,
[class*="card"]:hover {
  box-shadow: 0 8px 24px rgba(33, 39, 51, 0.14);
  transform: translateY(-2px);
}

/* Button hover/active refinement using existing variables */
button:hover,
[class*="btn"]:hover {
  background-color: var(--primary-hover);
  box-shadow: 0 6px 18px rgba(255, 119, 0, 0.25);
}

button:active,
[class*="btn"]:active {
  transform: translateY(1px);
  box-shadow: 0 2px 6px rgba(33, 39, 51, 0.12);
}

/* Consistent, accessible focus ring across interactive elements */
a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
[tabindex]:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: var(--radius);
}

/* Softer default shadow refinement for surfaces */
.surface,
[class*="surface"] {
  box-shadow: var(--shadow);
  border-radius: var(--radius);
}

/* Vertical spacing rhythm for stacked content blocks */
main > * + *,
.content > * + *,
section + section {
  margin-top: 1.5rem;
}

/* Tighter rhythm for text elements within a block */
p + p,
li + li {
  margin-top: 0.5rem;
}

/* Form field spacing rhythm */
label + input,
label + select,
label + textarea {
  margin-top: 0.375rem;
}

input,
select,
textarea {
  border-radius: var(--radius);
  border: 1px solid var(--border);
}

input:focus,
select:focus,
textarea:focus {
  border-color: var(--accent);
}

/* Muted helper text refinement */
.muted,
small,
[class*="hint"] {
  color: var(--muted);
  line-height: 1.5;
}

/* Responsive tweaks: tighten spacing and shadows on small screens */
@media (max-width: 640px) {
  main > * + *,
  .content > * + *,
  section + section {
    margin-top: 1rem;
  }

  .card,
  [class*="card"] {
    box-shadow: 0 2px 8px rgba(33, 39, 51, 0.1);
  }

  .card:hover,
  [class*="card"]:hover {
    transform: none;
  }
}

/* Improve tap targets and spacing on medium screens */
@media (min-width: 641px) and (max-width: 1024px) {
  main > * + *,
  .content > * + *,
  section + section {
    margin-top: 1.25rem;
  }
}

/* Selection color aligned with theme */
::selection {
  background: var(--primary);
  color: var(--surface);
}

